4: import { Button, IconButton } from '@carbon/react';
5: import { SingleSpaContext } from 'single-spa-react';
6: import { ComponentContext, useLayoutType } from '@openmrs/esm-react-utils';
7: import { type OpenedWindow } from '@openmrs/esm-extensions';
8: import { launchWorkspace2, useWorkspace2Store } from '../workspace2';
9: import styles from './action-menu-button2.module.scss';
10: 
11: interface TagsProps {
12:   getIcon: (props: object) => JSX.Element;
13:   hasUnsavedChanges: boolean;
14:   tagContent?: React.ReactNode;
15: }
16: 
17: function Tags({ getIcon, hasUnsavedChanges, tagContent }: TagsProps) {
18:   return (
19:     <>
20:       {getIcon({ size: 16 })}
21: 
22:       {hasUnsavedChanges ? (
23:         <span className={styles.interruptedTag}>!</span>
24:       ) : (
25:         <span className={styles.countTag}>{tagContent}</span>
26:       )}
27:     </>
28:   );
29: }
