31: export interface ActionMenuButtonProps2 {
32:   icon: (props: object) => JSX.Element;
33:   label: string;
34:   tagContent?: string | React.ReactNode;
35:   workspaceToLaunch: {
36:     workspaceName: string;
37:     workspaceProps?: Record<string, any>;
38:     windowProps?: Record<string, any>;
39:   };
40: 
41:   /**
42:    * An optional callback function to run before launching the workspace.
43:    * If provided, the workspace will only be launched if this function returns true.
44:    * This can be used to perform checks or prompt the user before launching the workspace.
45:    * Note that this function does not run if the action button's window is already opened;
46:    * it will just restore (unhide) the window.
47:    *
48:    */
49:   onBeforeWorkspaceLaunch?: () => Promise<boolean>;
50: }
51: 
52: /**
53:  * The ActionMenuButton2 component is used to render a button in the action menu of a workspace group.
54:  * The button is associated with a specific workspace window, defined in routes.json of the app with the button.
55:  * When one or more workspaces within the window are opened, the button will be highlighted:
56:  * bold blue when the window is focused (un-minimized and in front), green when unfocused.
57:  * If any workspace in the window has unsaved changes, an exclamation mark will be displayed
58:  * on top of the icon.
59:  *
60:  * On clicked, The button either:
61:  * 1. hides the workspace window if it is opened and focused; or
62:  * 2. restores the workspace window if it is opened and unfocused; or
63:  * 3. launches a workspace from within that window, if the window is not opened.
64:  *
65:  */
66: export const ActionMenuButton2: React.FC<ActionMenuButtonProps2> = ({
67:   icon: getIcon,
68:   label,
69:   tagContent,
70:   workspaceToLaunch,
71:   onBeforeWorkspaceLaunch,
72: }) => {
73:   const layout = useLayoutType();
74:   const { openedWindows, restoreWindow, hideWindow, isMostRecentlyOpenedWindowHidden } = useWorkspace2Store();
75: 
76:   const { extension } = useContext(ComponentContext);
77:   const openedWindowIndex = openedWindows.findIndex((w) => w.windowName === extension?.extensionId);
78:   // can be undefined if the window is not opened
79:   const window: OpenedWindow | undefined = openedWindows[openedWindowIndex];
80:   const isWindowOpened = window != null;
81:   const isWindowHidden =
82:     isWindowOpened && (openedWindowIndex < openedWindows.length - 1 || isMostRecentlyOpenedWindowHidden);
83:   const isWindowFocused = isWindowOpened && !isWindowHidden;
84:   const hasUnsavedChanges = window?.openedWorkspaces.some((w) => w.hasUnsavedChanges) ?? false;
85: 
86:   const onClick = async () => {
87:     if (isWindowOpened) {
88:       if (isWindowHidden) {
89:         restoreWindow(window.windowName);
90:       } else {
91:         hideWindow();
92:       }
93:     } else {
94:       const shouldLaunch = await (onBeforeWorkspaceLaunch?.() ?? true);
95:       if (shouldLaunch) {
96:         const { workspaceName, workspaceProps, windowProps } = workspaceToLaunch;
97:         launchWorkspace2(workspaceName, workspaceProps, windowProps);
98:       }
99:     }
100:   };
101: 
102:   if (layout === 'tablet' || layout === 'phone') {
103:     return (
104:       <Button
105:         className={classNames(styles.container, {
106:           [styles.active]: isWindowOpened && !isWindowFocused,
107:           [styles.focused]: isWindowFocused,
108:         })}
109:         iconDescription={label}
110:         kind="ghost"
111:         onClick={onClick}
112:         role="button"
113:         tabIndex={0}
114:         size="md"
115:       >
116:         <span className={styles.elementContainer}>
117:           <Tags hasUnsavedChanges={hasUnsavedChanges} getIcon={getIcon} tagContent={tagContent} />
118:         </span>
119:         <span>{label}</span>
120:       </Button>
121:     );
122:   }
123: 
124:   return (
125:     <IconButton
126:       align="left"
127:       aria-label={label}
128:       className={classNames(styles.container, {
129:         [styles.active]: isWindowOpened && !isWindowFocused,
130:         [styles.focused]: isWindowFocused,
131:       })}
132:       enterDelayMs={300}
